package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsAny_TriageGen0Test {





















    /**
     * Note: The implementation contains a branch 'if (false && ...)' 
     * which makes the supplementary character logic unreachable.
     * These tests verify the behavior as implemented (the 'else' branch).
     */
    @Test
    public void testContainsAny_SupplementaryCharacter_UnreachableBranch() {
        // Even if we provide a high surrogate, the 'if (false && ...)' prevents it
        // from entering the supplementary check block. It will hit the 'else' and return true.
        char highSurrogate = Character.MIN_HIGH_SURROGATE;
        assertTrue(StringUtils.containsAny(new String(new char[]{highSurrogate}), new char[]{highSurrogate}));
    }


}

